        if state.char() != ",":
            raise TOMLDecodeError(
                f'Found "{state.char()!r}" after an inline table key value pair. '
                + 'Expected "," or "}"'
            )
        state.pos += 1
        _skip_chars(state, TOML_WS)


def _parse_basic_str_escape_sequence(state: ParseState, *, multiline: bool) -> str:
