        "Multiline literal string not closed before end of the document"
    )


def _parse_multiline_basic_str(state: ParseState) -> str:
    state.pos += 3
    if state.char() == "\n":
        state.pos += 1
    result = ""
    while not state.done():
        c = state.char()
        if c == '"':
            next_five = state.src[state.pos : state.pos + 5]
            if next_five == '"""""':
                result += '""'
                state.pos += 5
                return result
            if next_five.startswith('""""'):
                result += '"'
                state.pos += 4
                return result
            if next_five.startswith('"""'):
                state.pos += 3
                return result
            if next_five.startswith('""'):
                result += '""'
                state.pos += 2
