def _create_list_rule(state: ParseState) -> None:
    state.pos += 2
    _skip_chars(state, TOML_WS)
    key_parts = _parse_key(state)

    if state.out.is_frozen(key_parts):
        raise TOMLDecodeError(
            f'Can not mutate immutable namespace "{".".join(key_parts)}"'
        )
